export interface WhatsAppChat {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone: string;
  lastMessage: string;
  lastMessageAt: string;
  status: 'unread' | 'read' | 'archived';
  priority: 'high' | 'normal' | 'low';
  assignedTo?: string;
  tags: string[];
  messages: WhatsAppMessage[];
  unreadCount: number;
  createdAt: string;
  updatedAt: string;
}

export interface WhatsAppMessage {
  id: string;
  chatId: string;
  content: string;
  type: 'text' | 'image' | 'video' | 'audio' | 'document' | 'location' | 'template';
  direction: 'inbound' | 'outbound';
  status: 'pending' | 'sent' | 'delivered' | 'read' | 'failed';
  timestamp: string;
  mediaUrl?: string;
  templateId?: string;
}

export interface WhatsAppTemplate {
  id: string;
  name: string;
  content: string;
  category: string;
  subcategory: string;
  variables: string[];
  status: 'active' | 'draft' | 'archived';
  usageCount: number;
  createdAt: string;
  isPreloaded: boolean;
}

export interface WhatsAppCampaign {
  id: string;
  name: string;
  description: string;
  templateId?: string;
  message: string;
  recipients: string[];
  recipientCount: number;
  status: 'draft' | 'scheduled' | 'sending' | 'sent' | 'failed' | 'cancelled';
  scheduledAt?: string;
  sentAt?: string;
  sentCount: number;
  deliveredCount: number;
  readCount: number;
  failedCount: number;
  cost: number;
  createdAt: string;
  createdBy: string;
}

export interface AutomationFlow {
  id: string;
  name: string;
  description: string;
  trigger: string;
  triggerType: 'keyword' | 'new_customer' | 'inquiry' | 'purchase' | 'appointment' | 'custom';
  steps: AutomationStep[];
  status: 'active' | 'paused' | 'draft';
  stats: { triggered: number; completed: number; lastTriggered?: string };
  createdAt: string;
  updatedAt: string;
}

export interface AutomationStep {
  id: string;
  order: number;
  type: 'message' | 'wait' | 'condition' | 'action' | 'tag';
  config: Record<string, any>;
  delay?: number;
}

